// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address sender, uint256 value) public {
        vm.assume(sender != address(0));
        value = bound(value, 0, 1 ether);

        vm.deal(sender, value);

        uint256 before = c.depositsCount();

        vm.prank(sender);
        (bool ok,) = address(c).call{value: value}("");
        require(ok);

        assertTrue(c.depositsCount() >= before);
    }
}
